-- Verbatim deployed procedure exported during diagnosis; isolated test fixture.
-- Not a deployment or rollback script. Its CREATE must run in the scratch DB.
/* Header scanner fixture: CREATE PROCEDURE in a comment is not the SQL header.
   /* A nested block comment must be skipped without changing its contents. */
*/
CREATE   PROCEDURE     academiconline.usp_SyncFacultyPublicationReviewCandidatesForDepartment (     @DepartmentId BIGINT ) AS BEGIN     SET NOCOUNT ON;     SET XACT_ABORT ON;      DECLARE         @SourceRows BIGINT = 0,         @UpdatedRows INT = 0,         @InsertedRows INT = 0,         @RetiredRows INT = 0;       IF @DepartmentId IS NULL     BEGIN         THROW 51100,             'DepartmentId is required.',             1;     END;       IF OBJECT_ID(         'tempdb..#CurrentReviewSource'     ) IS NOT NULL     BEGIN         DROP TABLE #CurrentReviewSource;     END;       SELECT         ReviewSourceKey,          FacultyKey,         PublicationKey,          DepartmentId,         DepartmentName,         DivisionName,          UvaUserId,         FacultyDisplayName,         Email,         Position,         Orcid,          PublicationIdentitySource,         SourceAuthorId,          RelationshipSource,         RelationshipSourceProvider,         RelationshipSourceAuthorId,          AcademicOnlinePublicationId,         OpenAlexId,          Doi,         DoiNormalized,          Title,         Venue,         YearText,         PublicationYear,         CitationCount,         Verified,         Link,          DataRunId,         RelationshipSnapshotRunId,          IsInCurrentReportingWindow,          DepartmentDataComplete      INTO #CurrentReviewSource      FROM         academiconline.vw_FacultyPublicationReviewUniverse      WHERE DepartmentId =           @DepartmentId;       SELECT         @SourceRows = COUNT_BIG(*)      FROM #CurrentReviewSource;       IF @SourceRows = 0     BEGIN         THROW 51101,             'Review synchronization aborted: no review-universe rows exist for this department.',             1;     END;       IF EXISTS     (         SELECT             FacultyKey,             PublicationKey          FROM #CurrentReviewSource          GROUP BY             FacultyKey,             PublicationKey          HAVING COUNT_BIG(*) > 1     )     BEGIN         THROW 51102,             'Review synchronization aborted: duplicate FacultyKey + PublicationKey rows exist.',             1;     END;       BEGIN TRANSACTION;       /* --------------------------------------------------------        Update existing candidates        -------------------------------------------------------- */      UPDATE c     SET         c.ReviewSourceKey =             s.ReviewSourceKey,          c.DepartmentId =             s.DepartmentId,          c.DepartmentName =             LEFT(s.DepartmentName, 512),          c.DivisionName =             LEFT(s.DivisionName, 512),          c.UvaUserId =             LEFT(s.UvaUserId, 512),          c.FacultyDisplayName =             LEFT(s.FacultyDisplayName, 512),          c.Email =             LEFT(s.Email, 512),          c.Position =             LEFT(s.Position, 512),          c.Orcid =             LEFT(s.Orcid, 512),          c.PublicationIdentitySource =             LEFT(s.PublicationIdentitySource, 30),          c.SourceAuthorId =             LEFT(s.SourceAuthorId, 256),          c.RelationshipSource =             LEFT(s.RelationshipSource, 60),          c.RelationshipSourceProvider =             LEFT(s.RelationshipSourceProvider, 60),          c.RelationshipSourceAuthorId =             LEFT(s.RelationshipSourceAuthorId, 256),          c.AcademicOnlinePublicationId =             LEFT(s.AcademicOnlinePublicationId, 128),          c.OpenAlexId =             LEFT(s.OpenAlexId, 128),          c.Doi =             LEFT(s.Doi, 512),          c.DoiNormalized =             LEFT(s.DoiNormalized, 512),          c.Title =             s.Title,          c.Venue =             LEFT(s.Venue, 512),          c.YearText =             LEFT(s.YearText, 50),          c.PublicationYear =             s.PublicationYear,          c.CitationCount =             s.CitationCount,          c.Verified =             s.Verified,          c.Link =             LEFT(s.Link, 1024),          c.LastSeenDataRunId =             s.DataRunId,          c.LastSeenAtUtc =             SYSUTCDATETIME(),          /* Known association remains review-eligible */         c.IsCurrentSource =             1,          /* Separate operational reporting state */         c.IsInCurrentReportingWindow =             s.IsInCurrentReportingWindow,          c.UpdatedAtUtc =             SYSUTCDATETIME()      FROM         academiconline.FacultyPublicationReviewCandidate c      JOIN #CurrentReviewSource s         ON s.FacultyKey =            c.FacultyKey         AND s.PublicationKey =            c.PublicationKey;      SET @UpdatedRows = @@ROWCOUNT;       /* --------------------------------------------------------        Insert new known associations        -------------------------------------------------------- */      INSERT INTO         academiconline.FacultyPublicationReviewCandidate     (         ReviewSourceKey,          FacultyKey,         PublicationKey,          DepartmentId,         DepartmentName,         DivisionName,          UvaUserId,         FacultyDisplayName,         Email,         Position,         Orcid,          PublicationIdentitySource,         SourceAuthorId,          RelationshipSource,         RelationshipSourceProvider,         RelationshipSourceAuthorId,          AcademicOnlinePublicationId,         OpenAlexId,          Doi,         DoiNormalized,          Title,         Venue,         YearText,         PublicationYear,         CitationCount,         Verified,         Link,          FirstSeenDataRunId,         LastSeenDataRunId,          FirstSeenAtUtc,         LastSeenAtUtc,          IsCurrentSource,         IsInCurrentReportingWindow,          CreatedAtUtc,         UpdatedAtUtc     )     SELECT         s.ReviewSourceKey,          s.FacultyKey,         s.PublicationKey,          s.DepartmentId,         LEFT(s.DepartmentName, 512),         LEFT(s.DivisionName, 512),          LEFT(s.UvaUserId, 512),         LEFT(s.FacultyDisplayName, 512),         LEFT(s.Email, 512),         LEFT(s.Position, 512),         LEFT(s.Orcid, 512),          LEFT(s.PublicationIdentitySource, 30),         LEFT(s.SourceAuthorId, 256),          LEFT(s.RelationshipSource, 60),         LEFT(s.RelationshipSourceProvider, 60),         LEFT(s.RelationshipSourceAuthorId, 256),          LEFT(s.AcademicOnlinePublicationId, 128),         LEFT(s.OpenAlexId, 128),          LEFT(s.Doi, 512),         LEFT(s.DoiNormalized, 512),          s.Title,         LEFT(s.Venue, 512),         LEFT(s.YearText, 50),         s.PublicationYear,         s.CitationCount,         s.Verified,         LEFT(s.Link, 1024),          s.DataRunId,         s.DataRunId,          SYSUTCDATETIME(),         SYSUTCDATETIME(),          1,         s.IsInCurrentReportingWindow,          SYSUTCDATETIME(),         SYSUTCDATETIME()      FROM #CurrentReviewSource s      WHERE NOT EXISTS     (         SELECT 1          FROM             academiconline.FacultyPublicationReviewCandidate c          WHERE c.FacultyKey =               s.FacultyKey            AND c.PublicationKey =               s.PublicationKey     );      SET @InsertedRows = @@ROWCOUNT;       /* --------------------------------------------------------        Only retire an association that is absent from the        entire known review universe.        -------------------------------------------------------- */      UPDATE c     SET         c.IsCurrentSource = 0,         c.IsInCurrentReportingWindow = 0,         c.UpdatedAtUtc = SYSUTCDATETIME()      FROM         academiconline.FacultyPublicationReviewCandidate c      WHERE c.DepartmentId =           @DepartmentId        AND c.IsCurrentSource = 1        AND NOT EXISTS       (           SELECT 1            FROM #CurrentReviewSource s            WHERE s.FacultyKey =                 c.FacultyKey              AND s.PublicationKey =                 c.PublicationKey       );      SET @RetiredRows = @@ROWCOUNT;       COMMIT TRANSACTION;       SELECT         DepartmentId =             @DepartmentId,          SourceRows =             @SourceRows,          UpdatedRows =             @UpdatedRows,          InsertedRows =             @InsertedRows,          RetiredRows =             @RetiredRows,          CurrentCandidateRows =         (             SELECT COUNT_BIG(*)              FROM                 academiconline.FacultyPublicationReviewCandidate              WHERE DepartmentId =                   @DepartmentId                AND IsCurrentSource = 1         );  END;
GO
